use vstd::prelude::*;

verus! {

/// A small helper predicate for readability.
spec fn is_lowercase_letter(c: char) -> bool {
    'a' <= c && c <= 'z'
}

/// Specification: pluralize a word represented as a sequence of chars.
/// Rule:
/// - if last char is 's' => append "es"
/// - else => append "s"
spec fn plural_spec(w: Seq<char>) -> Seq<char> {
    if w.last() == 's' {
        w + seq!['e', 's']
    } else {
        w + seq!['s']
    }
}

fn solve(s: &Vec<char>) -> (result: Vec<char>)
    requires
        s@.len() > 0,
        forall|i: int| 0 <= i < s@.len() ==> is_lowercase_letter(s@[i]),
    ensures
        result@ == plural_spec(s@),
        // (optional but useful) output characters are still lowercase letters
        forall|i: int| 0 <= i < result@.len() ==> is_lowercase_letter(result@[i]),
{
    let n = s.len();
    // Since n > 0 (by requires), n-1 is safe.
    let last = s[n - 1];

    let mut out: Vec<char> = Vec::new();
    let mut i: usize = 0;

    // Copy input into out
    while i < n
        invariant
            i <= n,
            out@ == s@.subrange(0, i as int),
            s@.len() == n as int,
            forall|k: int| 0 <= k < s@.len() ==> is_lowercase_letter(s@[k]),
        decreases n - i,
    {
        out.push(s[i]);
        i += 1;
    }

    // Append the appropriate suffix
    if last == 's' {
        out.push('e');
        out.push('s');

        // Prove the postconditions for this branch
        proof {
            // out@ is s@ + ['e','s']
            assert(out@ == s@ + seq!['e', 's']);
            // and plural_spec chooses that when last is 's'
            assert(plural_spec(s@) == s@ + seq!['e', 's']);
        }
    } else {
        out.push('s');

        proof {
            assert(out@ == s@ + seq!['s']);
            assert(plural_spec(s@) == s@ + seq!['s']);
        }
    }

    // Show output is lowercase letters
    proof {
        // From the loop invariant we know all original chars are lowercase.
        // We only appended 'e' and/or 's', which are lowercase.
        assert(is_lowercase_letter('s'));
        assert(is_lowercase_letter('e'));
    }

    out
}

} // verus!

